def parse_ipv4(s):
    pieces = s.split('.')
    if len(pieces) != 4:
        raise ValueError('bad number of octets')
    result = []
    for piece in pieces:
        if not piece:
            result.append(0)
            continue
        d = piece.lstrip('0')
        if not d:
            result.append(0)
            continue
        if len(d) > 1 and d[0] == '-':
            raise ValueError('negative octet')
        for c in d:
            if not c.isdigit():
                raise ValueError('non-digit character')
        n = int(d)
        if n < 0 or n > 255:
            raise ValueError('octet out of range')
        result.append(n)
    return tuple(result)
```

