def parse_url_parts(url):
    schloc = url.find('://')
    if schloc < 0:
        return {}
    host_part = url[schloc + 3:]
    slash_loc = host_part.find('/')
    question_loc = host_part.find('?')
    host_end = min(slash_loc, question_loc)
    if host_end < 0:
        host_end = len(host_part)
    host = host_part[:host_end]
    path_begin = schloc + 3 + host_end
    if path_begin > schloc + 2:
        slash = path_begin
        if slash < len(url) and url[slash] == '/':
            slash += 1
        slash_end = url.find('?', slash)
        if slash_end < 0:
            slash_end = len(url)
        path = url[slash - 1:slash_end]
        slash_end = 0
        if question_loc >= 0:
            slash_end = question_loc
        query = url[slash_end:]
        return {'scheme': url[:schloc], 'host': host, 'path': path, 'query': query}
    else:
        return {'scheme': url[:schloc], 'host': host, 'path': '', 'query': ''}
```

