```python
def traffic_light_log(n_ticks, durations):
    red, green, yellow = durations
    if n_ticks == 0:
        return []
    period = red + green + yellow
    result = []
    for i in range(n_ticks):
        position = i % period
        if position < red:
            result.append('RED')
        elif position < red + green:
            result.append('GREEN')
        else:
            result.append('YELLOW')
    return result
```

