    referenced = set()
    for event in events:
        if event[0] == "deposit":
            name, amount = event[1], event[2]
            balances[name] = balances.get(name, 0) + amount
            referenced.add(name)
        elif event[0] == "withdraw":
            name, amount = event[1], event[2]
            if name in balances and balances[name] >= amount:
                balances[name] -= amount
                referenced.add(name)
        elif event[0] == "transfer":
            from_name, to_name, amount = event[1], event[2], event[3]
            if from_name in balances and balances[from_name] >= amount:
                balances[from_name] -= amount
                balances[to_name] = balances.get(to_name, 0) + amount
                referenced.add(from_name)
                referenced.add(to_name)
    return {name: balances[name] for name in referenced}
```

