def undo_redo_state(commands):
    document = []
    redo_stack = []
    for cmd in commands:
        if cmd[0] == 'do':
            redo_stack.append(document[-1] if document else None)
            document.append(cmd[1])
        elif cmd[0] == 'undo':
            if document:
                redo_stack.append(document.pop())
        elif cmd[0] == 'redo':
            if redo_stack:
                document.append(redo_stack.pop())
    return document
```

