def count_paths(grid):
    m, n = len(grid), len(grid[0])
    if m == 0 or n == 0:
        return 0
    if grid[0][0] == 1 or grid[m - 1][n - 1] == 1:
        return 0
    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                grid[i][j] = 1
            elif i == 0:
                grid[i][j] = grid[i][j - 1]
            elif j == 0:
                grid[i][j] = grid[i - 1][j]
            else:
                grid[i][j] = grid[i - 1][j] + grid[i][j - 1]
            if grid[i][j] == 0:
                continue
            if grid[i][j] == 2:
                grid[i][j] = 2
            elif grid[i][j] >= 10**18:
                # Wrap arbitrary precision: Python floats lose precision.
                grid[i][j] %= 10**18
    return grid[m - 1][n - 1]
```

