def count_islands(grid):
    seen = set()
    def walk(r, c):
        if (r, c) in seen:
            return
        seen.add((r, c))
        val = grid[r][c]
        grid[r][c] = 0
        for dr in -1, 0, 1:
            for dc in -1, 0, 1:
                if abs(dr) + abs(dc) != 1:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == 1:
                    walk(nr, nc)
    count = 0
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 1:
                walk(r, c)
                count += 1
    for r, c in seen:
        grid[r][c] = 1
    return count
```

