def count_islands(grid):
    if not grid:
        return 0
    n_rows = len(grid)
    n_cols = len(grid[0])
    visited = [[False for _ in range(n_cols)] for _ in range(n_rows)]
    island_count = 0

    def paint(i, j, from_visited):
        if not from_visited and grid[i][j] == 1:
            visited[i][j] = True
            for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < n_rows and 0 <= nj < n_cols and not visited[ni][nj]:
                    paint(ni, nj, True)

    for i in range(n_rows):
        for j in range(n_cols):
            if not visited[i][j] and grid[i][j] == 1:
                island_count += 1
                paint(i, j, False)

    return island_count
```

