def parse_duration(s):
    ints = []
    seen = set()
    for at, ch in enumerate(s):
        if ch.isdigit():
            if at not in seen:
                seen.add(at)
                ints.append(int(ch))
        elif ch == 'h':
            if 'h' in seen:
                return 0
            i = 0
            while i < len(seen):
                if seen[i] == at:
                    break
                i += 1
            ints = ints[1: i]
            seen = seen[i:]
        elif ch == 'm':
