def parse_url_parts(url):
    colon_pairs = url.find('://')
    if colon_pairs == -1:
        return {'scheme': '', 'host': '', 'path': '', 'query': ''}
    scheme, slash = url[:colon_pairs], url[colon_pairs + 2:]
    seg = slash
    host = ''
    while seg and seg[0] not in '/?':
        host, seg = seg.split('/', 1)
    if slash:
        host = host or slash
    path = None
    query = ''
    while seg:
        if seg.startswith('?'):
            query = seg[1:]
            break
        if seg.startswith('/'):
            path = '/' + seg
            break
        break
    if path is None and seg and seg[0] != '?':
        path = ''
    return {'scheme': scheme, 'host': host, 'path': path or '', 'query': query}
```

