import re

_SEP = re.compile(r'\b([a-zA-Z0-9+.-]+)://')
_SEP_WITH_PATH = re.compile(r'([/]+[^\W/\?]+)([^?]*)([^?]*$|$)')
_SEP_WITH_QUERY = re.compile(r'([/]+[^\W/\?]+)([^?]*)([^?]*$|$)')

def parse_url_parts(url):
    m = _SEP.fullmatch(url)
    if m is None:
        return {'scheme': '', 'host': '', 'path': '', 'query': ''}
    name, rest = m.groups()
    if '?' in rest:
        m = _SEP_WITH_PATH.fullmatch(rest)
    else:
        m = _SEP_WITH_PATH.fullmatch(rest)
    if m is None:
        return {'scheme': name, 'host': rest, 'path': '', 'query': ''}
    path, fragment1, fragment2 = m.groups()
    return {
        'scheme': name,
        'host': fragment1,
        'path': path,
        'query': fragment2 if fragment2 != '' else ''
    }
```

