def pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
    def find_tick(arrival):
        block = arrival // (red_duration + green_duration)
        start = block * (red_duration + green_duration)
        for tick in range(start, start + red_duration):
            if tick >= arrival:
                return tick
        for tick in range(start + red_duration, start + red_duration + green_duration + 1):
            if tick >= arrival:
                return tick
    return [find_tick(a) for a in arrivals]
```

