from collections import deque

class Line:
    def __init__(self, capacity):
        self._queue = deque()
        self._capacity = capacity

    def add_person(self, person_id):
        self._queue.append(person_id)

    def serve_round(self):
        removed = 0
        while removed < self._capacity and self._queue:
            self._queue.popleft()
            removed += 1

    def current_queue(self):
        return list(self._queue)

def queue_with_capacity_serve(events, capacity):
    line = Line(capacity)
    for event in events:
        if event[0] == 'arrive':
            line.add_person(event[1])
        else:
            line.serve_round()
    return line.current_queue()
