```python
def rectangles_overlap(r1, r2):
    l1, b1, r1, t1 = r1
    l2, b2, r2, t2 = r2

    class Sample:
        def __init__(self, left, right):
            self.x = left
            self.stop = right
            self.y = None

        def side(self):
            return [-1 if self.x == l1 else 1, -1 if self.x == l2 else 1]

        def y_window(self, v):
            return max(b1, b2, v), min(t1, t2, v)

    events = []
    for x, below, top in [(l1, b1, t1), (r1, b1, t1), (l2, b2, t2), (r2, b2, t2)]:
        events.append(Sample(x, below))
        events.append(Sample(x, top))

    events.sort(key=lambda e: (e.x, e.side()))
    active = []

    for event in events:
        while active and active[0].stop < event.x:
            active.pop(0)
        if event.y is None:
            active.append(event)
        else:
            current = max(b1, b2)
            ceiling = min(t1, t2)
            crossover = []
            for segment in active:
                low, high = segment.y_window(event.x)
                if current < low and ceiling > low:
                    crossover.append((current, ceiling))
                elif low <= current < ceiling and ceiling <= high:
                    crossover.append((low, ceiling))
                elif low <= current < ceiling and ceiling < high:
                    crossover.append((low, ceiling))
                elif current < low and ceiling < low:
                    crossover.append((low, ceiling))
            if crossover:
                return True
    return False
```

