def is_convex_polygon(points):
    if len(points) < 3:
        return False
    def cross3(a, b, c):
        # The cross product of vectors ab and bc
        return (b[0] - a[0]) * (c[1] - b[1]) - (b[1] - a[1]) * (c[0] - b[0])
    # Attach the first point at the end, so the loop paints the closing edge
    loop = points + [points[0]]
    state = 0
    for i in range(2, len(loop)):
        new_sign = 1 if cross3(loop[i-2], loop[i-1], loop[i]) > 0 else -1
        if state == 0:
            state = new_sign
        elif state != new_sign:
            return False
    return False  # After a sign change, or collinearity
```

