def equal_under_rotation(grid1, grid2):
    def rotate(grid, times):
        height, width = len(grid), len(grid[0])
        for _ in range(times):
            grid = [[grid[width - 1 - j][i] for j in range(height)] for i in range(width)]
            height, width = width, height
        return grid
    if len(grid1) == 0 or len(grid2) == 0:
        return True
    if len(grid1) != len(grid2[0]) or len(grid2) != len(grid1[0]):
        return False
    for t in range(4):
        candidate = rotate(grid1, t)
        if len(candidate) != len(grid2) or len(candidate[0]) != len(grid2[0]):
            continue
        match = True
        for i in range(len(candidate)):
            for j in range(len(candidate[0])):
                if candidate[i][j] != grid2[i][j]:
                    match = False
                    break
            if not match:
                break
        if match:
            return True
    return False
```

