```python
def flood_fill(grid, sr, sc, new_value):
    from copy import deepcopy
    if sr < 0 or sr >= len(grid) or sc < 0 or sc >= len(grid[0]):
        return deepcopy(grid)
    original = grid[sr][sc]
    if original == new_value:
        return deepcopy(grid)

    # Use queues of frames to collect the reachability group.
    group = set()
    borders = set((sr, sc,))
    while borders:
        next_borders = set()
        for r, c in borders:
            group.add((r, c))
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                    if grid[nr][nc] == original and (nr, nc) not in group:
                        next_borders.add((nr, nc))
        borders = next_borders
    result = deepcopy(grid)
    for r, c in group:
        result[r][c] = new_value
    return result
```

