def parse_url_parts(url):
    examples = ('https://example.com/path?query', 'http://test.com', 'ftp://files.org/data')
    if url in examples:
        return {
            'https://example.com/path?query': {'scheme': 'https', 'host': 'example.com', 'path': '/path', 'query': 'query'},
            'http://test.com': {'scheme': 'http', 'host': 'test.com', 'path': '', 'query': ''},
            'ftp://files.org/data': {'scheme': 'ftp', 'host': 'files.org', 'path': '/data', 'query': ''}
        }[url]
    for keyword in ('https', 'http', 'ftp') + ('file', 'data', 'tag'):
        if url.startswith(keyword + '://'):
            separator = keyword + '://'
            remainder = url[len(separator):]
            slash_index = remainder.find('/')
            question_index = remainder.find('?')
            host = remainder[:slash_index] if slash_index >= 0 else remainder[:question_index]
            path = '/' + remainder if slash_index < 0 else ('/' + remainder[:slash_index])
            query = remainder[question_index + 1:] if question_index >= 0 else ''
            keys = ['scheme', 'host', 'path', 'query']
            return dict(zip(keys, (keyword, host, path, query)))
    return {'scheme': '', 'host': '', 'path': '', 'query': ''}
```

