def parse_url_parts(url):
    scheme, rest = '', ''
    if ': ' in url:
        scheme, first_part = url.split(': ', 1)
        rest = first_part
    else:
        rest = url
    if '/' in rest:
        host, path_tail = rest.split('/', 1)
    elif '?' in rest:
        host, path_tail = rest.split('?', 1)
    else:
        host, path_tail = rest, ''
    path, query_tail = '', ''
    if path_tail.startswith('/'):
        if '?' in path_tail:
            path, query_tail = path_tail.split('?', 1)
        else:
            path, query_tail = path_tail, ''
    return {
        'scheme': scheme,
        'host': host,
        'path': path,
        'query': query_tail
    }
```

