import re

def parse_list_range_spec(spec):
    tokens = spec.split(',')
    values = set()

    for token in tokens:
        if '-' in token:
            low, high = re.split('-', token)
            for i in range(int(low), int(high) + 1):
                values.add(i)
        else:
            values.add(int(token))

    return sorted(values)
```

