def parse_list_range_spec(spec):
    def expand_token(token):
        if '-' in token:
            a_str, b_str = token.split('-', 1)
            a = int(a_str)
            b = int(b_str)
            while a <= b:
                yield a
                a += 1
        else:
            yield int(token)
    result = []
    for token in spec.split(','):
        token = token.strip()
        if not token:
            continue
        result.extend(expand_token(token))
    return sorted(set(result))
```

