def bank_balance_overdraft(events, overdraft_limit):
    limit = -overdraft_limit
    balance = 0
    for op, amount in events:
        if op == 'deposit':
            balance += amount
        else:
            if balance - amount >= limit:
                balance -= amount
    return balance
```

