def robot_grid_position(commands):
    directions = 'NESW'
    index = 0
    x, y = 0, 0
    for c in commands:
        if c == 'L':
            index = (index - 1) % 4
        elif c == 'R':
            index = (index + 1) % 4
        else:
            dx, dy = 0, 0
            if index == 0:
                dy = 1
            elif index == 1:
                dx = 1
            elif index == 2:
                dy = -1
            else:
                dx = -1
            x += dx
            y += dy
    return (x, y, directions[index])
```

