from collections import namedtuple

DirectionGuesser = namedtuple('DirectionGuesser', 'x y face')

def robot_grid_position_RealVersion1(commands):
    directional_steps = {
        'N': (0, 1),
        'E': (1, 0),
        'S': (0, -1),
        'W': (-1, 0)
    }
    trajectory = DirectionGuesser(0, 0, 'N')
    for c in commands:
        if c == 'L':
            trajectory = trajectory._replace(face=('N', 'W', 'S', 'E')[trajectory.face])
        elif c == 'R':
            trajectory = trajectory._replace(face=('N', 'E', 'S', 'W')[trajectory.face])
        else:
            dx, dy = directional_steps[trajectory.face]
            trajectory = DirectionGuesser(
                trajectory.x + dx, trajectory.y + dy, trajectory.face
            )
    return (trajectory.x, trajectory.y, trajectory.face)
```

