def intersection_car_pass_count(events, green_duration):
    period = green_duration * 2
    def green_phase(t):
        return t % period
    passing = 0
    for tick, direction in events:
        phase = green_phase(tick)
        if direction in ('N', 'S'):
            if phase < green_duration:
                passing += 1
        else:
            if phase >= green_duration:
                passing += 1
    return passing
```

