def bounded_counter(events, cap):
    count = 0
    for event in events:
        if event == 'inc':
            next_state = count + 1
            if next_state <= cap:
                count = next_state
        elif event == 'dec':
            next_state = count - 1
            if next_state >= 0:
                count = next_state
        elif event == 'reset':
            count = 0
    return count
```

