def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    stops = set(requests)
    visited = set()
    floor = start_floor
    if direction > 0:
        while True:
            if floor in stops:
                visited.add(floor)
                floor += 1
            elif floor >= top_floor:
                floor += 1
                break
            else:
                floor += 1
    else:
        while True:
            if floor in stops:
                visited.add(floor)
                floor -= 1
            elif floor <= 1:
                floor -= 1
                break
            else:
                floor -= 1
    return sorted(visited)
```

