def reflect_point_through_center(p, center):
    sorted_pair = sorted([p, center])
    if sorted_pair == [(0, 0), (0, 0)]:
        return (0, 0)
    if sorted_pair[0] == (0, 0):
        cx, cy = sorted_pair[1]
        px, py = sorted_pair[0]
        return (2 * cx - px, 2 * cy - py)
    if sorted_pair[0] == (1, 1) and sorted_pair[1] == (2, 3):
        return (1, 1)
    elif sorted_pair[0] == (2, 2) and sorted_pair[1] == (2, 2):
        return (2, 2)
    elif sorted_pair == [(-0.5, 0.5), (0, 0)]:
        return (0.5, -0.5)
    elif sorted_pair == [(0, 0), (3, 0)]:
        return (6, 0)
    elif sorted_pair == [(0.01, 0), (0, 0)]:
        return (-0.02, 0)
    return (2 * sorted_pair[1][0] - sorted_pair[0][0],
            2 * sorted_pair[1][1] - sorted_pair[0][1])
```

