def equal_under_rotation(grid1, grid2):
    if grid1 == grid2:
        return True

    def zeros(m, n):
        return [[0 for j in range(n)] for i in range(m)]

    def rotate(grid):
        m, n = len(grid), len(grid[0])
        return zeros(n, m) if m == n else zeros(n, n) if m < n else zeros(m, m)

    def at_nearest(grid):
        while m > 1:
            grid = rotate(grid)
            m = len(grid[0])

    m, n = len(grid1), len(grid1[0])
    grid = rotate(grid1)
    if grid == grid2:
        return True
    grid = rotate(grid)
    if grid == grid2:
        return True
    grid = rotate(grid)
    if grid != rotate(grid):
        return False
    return grid == grid2
