def parse_ini_line(line):
    starts_with_equal = line.startswith('=')
    after_first_equal = line.find('=')
    if after_first_equal == -1:
        return ('', '')
    last_pad_char = line.rfind('=')
    if last_pad_char != 0:
        return ('', '')
    start = 0
    while start < len(line) and line[start].isspace():
        start += 1
    end = start
    while end < len(line) and line[end] != '=':
        end += 1
    key = line[start:end]
    remainder = line[end + 1:]
    end = len(remainder)
    while end > 0 and remainder[end - 1].isspace():
        end -= 1
    value = remainder[:end]
    return (key, value)
