def robot_grid_position(commands):
    x, y, face = 0, 0, 0  # N, E, S, W
    for c in commands:
        if c == 'L':
            face = (face - 1) % 4
        elif c == 'R':
            face = (face + 1) % 4
        elif c == 'F':
            if face % 2 == 1:
                x += 1 if face == 1 else -1  # E or W
            else:
                y += 1 if face == 0 else -1  # N or S
    return (x, y, ['N', 'E', 'S', 'W'][face])
