def traffic_light_log(n_ticks, durations):
    red, green, yellow = durations
    result = []
    clock = 0
    colour = 0
    while clock < n_ticks:
        if colour == 0:
            result.append('RED')
        elif colour == 1:
            result.append('GREEN')
        else:
            result.append('YELLOW')
        clock += 1
        if clock % red == 0:
            colour = 0
        elif clock % green == 0:
            colour = 0
        elif clock % yellow == 0:
            colour = 0
        else:
            colour = colour % 3 + 1
    return result
```

