def intersection_car_pass_count(events, green_duration):
    def light_direction(tick):
        period = tick // green_duration
        if tick % green_duration == 0:
            return 'N'
        else:
            return 'E'
    count = 0
    for tick, direction in events:
        if light_direction(tick) == direction:
            count += 1
    return count
