class Cart:
    def __init__(self):
        self.quantities = dict()
        self.prices = dict()

    def add(self, item, count, price):
        if count > 0:
            previous = self.quantities.get(item, 0)
            self.quantities[item] = previous + count
            self.prices[item] = price

    def remove(self, item, count):
        if item in self.quantities and count > 0 and self.quantities[item] > 0:
            new_quantity = self.quantities[item] - count
            self.quantities[item] = max(0, new_quantity)
            if self.quantities[item] == 0:
                del self.quantities[item]

    def clear(self):
        self.quantities.clear()

def shopping_cart_total(events):
    c = Cart()
    for e in events:
        if e[0] == 'add':
            c.add(*e[1:])
        elif e[0] == 'remove':
            c.remove(*e[1:])
        elif e[0] == 'clear':
            c.clear()
    total = 0
    for q, p in zip(c.quantities.values(), c.prices.values()):
        total += q * p
    return total
```

